css=canonical_css(css)
js='''const search=document.querySelector('#search'),pending=document.querySelector('#onlypending');function filter(){let count=0;document.querySelectorAll('.queueitem').forEach(el=>{el.hidden=!(el.dataset.search.includes(search.value)&&(!pending.checked||el.dataset.pending==='true'));if(!el.hidden)count++});document.querySelector('#noresults').hidden=count>0}search.addEventListener('input',filter);pending.addEventListener('change',filter);document.querySelector('#clear').onclick=()=>{search.value='';pending.checked=false;filter();search.focus()};document.querySelectorAll('.queueitem').forEach(el=>el.onclick=()=>{document.querySelectorAll('.queueitem').forEach(x=>x.setAttribute('aria-pressed','false'));el.setAttribute('aria-pressed','true');document.querySelector('#selection').textContent=el.querySelector('b').textContent+' · 示例摘要：所属活动为日常好物演示。'});const modal=document.querySelector('dialog'),opener=document.querySelector('#openmodal');opener.onclick=()=>modal.showModal();document.querySelector('#cancel').onclick=()=>modal.close();modal.addEventListener('close',()=>opener.focus());modal.addEventListener('keydown',e=>{if(e.key==='Tab'){const es=[...modal.querySelectorAll('textarea,button')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===es[0]){e.preventDefault();es.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===es.at(-1)){e.preventDefault();es[0].focus()}}});document.querySelector('#noteform').onsubmit=e=>{e.preventDefault();document.querySelector('#selection').textContent='审核说明已保存在本页演示中；刷新后清除。';modal.close()};document.querySelector('#settings').onsubmit=e=>{e.preventDefault();document.querySelector('#saved').textContent='演示设置已保存至本页。刷新后恢复。'};document.querySelector('#setproperty').onclick=()=>{document.querySelector('[popovertarget="property"]').textContent='演示属性：待补充';document.querySelector('#property').hidePopover()};document.querySelector('#retry').onclick=()=>{document.querySelector('#retrystatus').textContent='演示重试完成；没有连接真实服务。'};'''
dialog='''<dialog aria-labelledby="dialogtitle"><form id="noteform"><h2 id="dialogtitle">添加审核说明</h2><p>作品 001 · 日常好物演示</p><p class="fine">本地演示。不会批准作品或触发付款。</p><label for="note">说明内容</label><textarea id="note" required autofocus placeholder="说明观察到的问题或下一步"></textarea><div class="toolbar"><button type="button" id="cancel" class="button secondary">取消</button><button class="button" type="submit">保存演示说明</button></div></form></dialog>'''
html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wringy · 视觉指南 v3</title><style>'+css+'</style><body><nav class="jump" aria-label="指南章节"><a href="#page-1">品牌</a><a href="#page-5">产品</a><a href="#page-8">交互演示</a><a href="#page-9">状态</a><small>独立设计草案 · 所有内容均为示例</small></nav>'+''.join(pages)+dialog+'<script>'+js+'</script></body></html>'
(P/'showcase.html').write_text(samples(html))
(P/'pattern-references.json').write_text(json.dumps({k:{'title':v[0],'url':v[1],'capture_family':'unknown','use':'pattern only; Wringy proposal'} for k,v in refs.items()},ensure_ascii=False,indent=2))
print('10-page self-contained showcase written')
